//! Phosphor icons (MIT) standing in for the SF Symbols of the original (docs/DESIGN.md 5.16).
//!
//! An [`Icon`] is a code point of the Phosphor font; regular and fill weights share it. Draw one
//! with [`Icon::rich`] / [`Icon::rich_fill`] in any egui text widget, or let the components do it.
//! The constants are generated by `tools/gen-icons.mjs`.
//!
//! Mapping notes: `xmark.octagon.fill` has no Phosphor twin and uses `X_CIRCLE` (fill);
//! `doc.badge.checkmark` uses `FILE_TEXT`; the stack-with-slash icon is `STACK` plus a slash the
//! screen draws over it; the "trigger" glyph uses `RECTANGLE`.

use egui::RichText;

use crate::ui::theme;

/// A Phosphor glyph.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Icon(pub(crate) char);

impl Icon {
    pub fn glyph(self) -> char {
        self.0
    }

    /// Regular weight at `size` dp.
    pub fn rich(self, size: f32) -> RichText {
        RichText::new(self.0.to_string()).font(theme::font_icon(size))
    }

    /// Fill weight at `size` dp (active/selected state, playback glyphs).
    pub fn rich_fill(self, size: f32) -> RichText {
        RichText::new(self.0.to_string()).font(theme::font_icon_fill(size))
    }

    /// Font to paint the glyph with.
    pub fn font(self, size: f32, fill: bool) -> egui::FontId {
        if fill {
            theme::font_icon_fill(size)
        } else {
            theme::font_icon(size)
        }
    }
}

include!("icons_table.rs");

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn code_points_are_in_the_private_use_area() {
        for icon in [
            Icon::GEAR_SIX,
            Icon::PLAY,
            Icon::TROPHY,
            Icon::LOCK_OPEN,
            Icon::X_CIRCLE,
        ] {
            assert!(
                ('\u{e000}'..='\u{f8ff}').contains(&icon.glyph()),
                "{icon:?}"
            );
        }
        assert_eq!(Icon::GEAR_SIX.glyph(), '\u{e272}');
    }
}
